"""Correct model/solver scientific claims against the pinned source."""
import re,json
from pathlib import Path
B=Path(__file__).resolve().parents[1]; changes=[]; missed=[]
def load(n):
 global p,t,o,chapter
 chapter=n;p=next((B/'chapters').glob(f'ch{n:02}_*/chapter.md'));o=p.read_text(encoding='utf-8-sig')
 backup=B/'.build/backups/scientific_revision'/p.parent.name/'twin_solver_input.md';backup.parent.mkdir(parents=True,exist_ok=True)
 if not backup.exists():backup.write_text(o,encoding='utf-8')
 t=backup.read_text(encoding='utf-8')
 # Protect the independently maintained figure results.
 global markers
 markers=re.findall(r'<!-- reviewed-notebook-results:start -->.*?<!-- reviewed-notebook-results:end -->',o,re.S)
 for i,m in enumerate(re.findall(r'<!-- reviewed-notebook-results:start -->.*?<!-- reviewed-notebook-results:end -->',t,re.S)):t=t.replace(m,f'PROTECTED_RESULTS_{i}')
def r(a,b):
 global t
 if a not in t:missed.append([chapter,a[:150]]);return
 t=t.replace(a,b);changes.append({'chapter':chapter,'before':a,'after':b})
def sub(a,b):
 global t
 t2,n=re.subn(a,lambda m:b,t,flags=re.S)
 if not n:missed.append([chapter,a[:150]]);return
 changes.append({'chapter':chapter,'pattern':a,'after':b});t=t2
def save():
 global t
 for i,m in enumerate(markers):t=t.replace(f'PROTECTED_RESULTS_{i}',m)
 p.write_text(t,encoding='utf-8')
